-- Datos INVENTADOS para ver el CRM lleno (7-oct-2026). Solo para la base de
-- pruebas (rhf-leads-preview) y el arnés de Node; nunca para producción.
-- Personas de mentira con «(demo)» en el nombre, correos @example.com y
-- teléfonos +57300555xxxx. Las fechas van relativas a hoy.
-- Se puede correr dos veces: no repite lo que ya existe.

INSERT INTO crm_contactos (creado_en, actualizado_en, nombre, telefono, correo, ciudad, idioma, fuente, fuente_ultima, pagina_entrada, canal, canal_ultimo, autorizacion_fecha, autorizacion_version, autorizacion_canal, autorizacion_evidencia, ultimo_contacto_en)
  SELECT strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-34 days', '-3 hours'), strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-34 days', '-3 hours'), 'Camila Rojas (demo)', '+573005550101', 'camila.demo@example.com', 'Cartagena', 'es', 'formulario', 'formulario', '/proyectos/doral-west', 'meta_ads', 'meta_ads', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-34 days', '-3 hours'), 'demo', 'otro', 'Dato de demostración, inventado (no es una persona real)', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-12 days')
  WHERE NOT EXISTS (SELECT 1 FROM crm_contactos WHERE correo = 'camila.demo@example.com');
INSERT INTO crm_oportunidades (contacto_id, creado_en, actualizado_en, tipo, etapa, etapa_desde, motivo_perdida, puntaje, interes, proposito, cerrada, canal, rango_presupuesto, pago, valor_estimado, espera_desde, primer_intento_en, minutos_respuesta, ultima_actividad_en, fase_contactado_en, fase_presentacion_en, fase_cotizacion_en, fase_cierre_en, proxima_accion, proxima_accion_en)
  SELECT id, strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-34 days', '-3 hours'), strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-12 days'), 'compra', 'propuesta', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-12 days'), NULL, 'A', 'doral-west', 'vivir', 0, 'meta_ads', '600_900', 'credito', 690000000, NULL, strftime('%Y-%m-%dT%H:%M:%fZ', strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-34 days', '-3 hours'), '+4 minutes'), 4, strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-12 days'), strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-33 days'), strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-26 days'), strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-12 days'), NULL, 'Llamar para cerrar la propuesta', date('now', '-5 hours', '+1 day')
  FROM crm_contactos c WHERE c.correo = 'camila.demo@example.com' AND NOT EXISTS (SELECT 1 FROM crm_oportunidades o WHERE o.contacto_id = c.id);
INSERT INTO crm_actividades (contacto_id, oportunidad_id, creado_en, tipo, texto, autor)
  SELECT c.id, o.id, strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-34 days', '-3 hours'), 'formulario', 'Dato de demostración. Llegó por meta_ads, campaña doral-west-oct.', 'sitio' FROM crm_contactos c JOIN crm_oportunidades o ON o.contacto_id = c.id
  WHERE c.correo = 'camila.demo@example.com' AND NOT EXISTS (SELECT 1 FROM crm_actividades a WHERE a.contacto_id = c.id);

