INSERT INTO agente_sincronizacion (fuente, ultimo_en, lotes, mensajes) SELECT 'atencion', strftime('%Y-%m-%dT%H:%M:%fZ', 'now'), 1, (SELECT COUNT(*) FROM agente_mensajes) WHERE NOT EXISTS (SELECT 1 FROM agente_sincronizacion WHERE fuente = 'atencion');
